def unwrap(x):
    return x[0] if isinstance(x, tuple) and x else x

def extract_ids(res):
    res = unwrap(res) or {}
    d = res.get("data", {})
    r = d.get("response_data", d)
    return r.get("id"), r.get("threadId"), r.get("display_url")
